/* Custom icons: your own SVGs, built in by tools/icons/build.py. Each is the inner markup of a
   24×24 SVG, cleaned by the build (shapes only, drawn in currentColor), so it's safe to insert. */
/* @icons:start generated by tools/icons/build.py from your icon SVGs; edit the SVGs, not this */
export const ICONS: Record<string, string> = {};
/* @icons:end */

// @icons:start generated by tools/icons/build.py
/** Names of the custom icons (tools/icons/build.py). Empty (never) until you add some. */
export type CustomIconName = never;
// @icons:end

/** Names of your custom icons, sorted. */
export const customIcons = Object.freeze(Object.keys(ICONS).sort()) as readonly CustomIconName[];

export function hasIcon(name: unknown): name is string {
  return typeof name === "string" && Object.prototype.hasOwnProperty.call(ICONS, name);
}
